import Foundation
import CoreML
import CoreVideo
import Accelerate
import AVFoundation

// DEC-130/131: on-device LEARNED shot front-end. A Swift/CoreML parity port of ops/detector_integrate.py: run the
// BallLaneDetector CenterNet on each (letterboxed) frame, decode the ball heat-map peak + the lane-geometry head.
// Used as the FALLBACK when the classical on-device tracker fails (BALL_TRACK_NOT_FOUND / sparse), so the on-device
// engine covers the same hard camera positions the server's learned path does. The compiled model class
// (`BallLaneDetector`) is generated by Xcode from Models/BallLaneDetector.mlpackage; absent → `shared` is nil and
// the caller stays classical-only.
nonisolated struct ODBallDet { let cx: Float; let cy: Float; let score: Float }
nonisolated struct ODLaneParams { let foulL: (Float, Float); let foulR: (Float, Float); let vp: (Float, Float) }

nonisolated final class OnDeviceLearnedDetector: @unchecked Sendable {   // immutable after init; MLModel is thread-safe
    static let shared: OnDeviceLearnedDetector? = {
        guard let d = try? OnDeviceLearnedDetector() else { return nil }
        return d
    }()

    nonisolated(unsafe) static var lastRaw: [[Double]] = []   // parity harness: per-frame [t, cx, cy] of the last buildTrack
    private let model: MLModel
    private let input = 512
    private let mean: [Float] = [0.485, 0.456, 0.406]
    private let std: [Float] = [0.229, 0.224, 0.225]

    /// Least-squares quadratic fit y = a·x² + b·x + c (3×3 normal equations, Cramer). nil if degenerate.
    private static func quadFit(_ x: [Double], _ y: [Double]) -> (Double, Double, Double)? {
        var S0 = 0.0, S1 = 0.0, S2 = 0.0, S3 = 0.0, S4 = 0.0, T0 = 0.0, T1 = 0.0, T2 = 0.0
        for i in 0..<x.count { let xi = x[i], yi = y[i], x2 = x[i] * x[i]
            S0 += 1; S1 += xi; S2 += x2; S3 += x2 * xi; S4 += x2 * x2; T0 += yi; T1 += xi * yi; T2 += x2 * yi }
        func det3(_ a: [[Double]]) -> Double {
            a[0][0]*(a[1][1]*a[2][2]-a[1][2]*a[2][1]) - a[0][1]*(a[1][0]*a[2][2]-a[1][2]*a[2][0]) + a[0][2]*(a[1][0]*a[2][1]-a[1][1]*a[2][0]) }
        let m = [[S4, S3, S2], [S3, S2, S1], [S2, S1, S0]], v = [T2, T1, T0]
        let d = det3(m); guard abs(d) > 1e-9 else { return nil }
        func col(_ a: [[Double]], _ ci: Int) -> [[Double]] { var r = a; for i in 0..<3 { r[i][ci] = v[i] }; return r }
        return (det3(col(m, 0)) / d, det3(col(m, 1)) / d, det3(col(m, 2)) / d)
    }

    /// A flat element reader for an MLMultiArray at its ACTUAL precision (the model is exported FLOAT16; reading
    /// fp16 bits as fp32 yields garbage). Assumes a contiguous buffer (true for these dense detector outputs).
    private static func reader(_ a: MLMultiArray) -> (Int) -> Float {
        switch a.dataType {
        case .float16:
            let p = a.dataPointer.assumingMemoryBound(to: Float16.self); return { Float(p[$0]) }
        case .float32:
            let p = a.dataPointer.assumingMemoryBound(to: Float.self); return { p[$0] }
        case .double:
            let p = a.dataPointer.assumingMemoryBound(to: Double.self); return { Float(p[$0]) }
        default:
            return { a[$0].floatValue }
        }
    }

    init() throws {
        // The generated class exposes its compiled URL; load the bare MLModel so we can read named outputs.
        guard let url = Bundle.main.url(forResource: "BallLaneDetector", withExtension: "mlmodelc") else {
            throw NSError(domain: "ls.learned", code: 1)
        }
        let cfg = MLModelConfiguration(); cfg.computeUnits = .all
        self.model = try MLModel(contentsOf: url, configuration: cfg)
    }

    /// Run the detector on one BGRA frame. Returns the ball peak (full-frame coords) over `thr`, and the lane params.
    func detect(_ px: CVPixelBuffer, rot: ODRotation, thr: Float = 0.3) -> (ball: ODBallDet?, lane: ODLaneParams?) {
        guard let buf = OnDeviceDecode.rotated(px, rot) else { return (nil, nil) }
        CVPixelBufferLockBaseAddress(buf, .readOnly); defer { CVPixelBufferUnlockBaseAddress(buf, .readOnly) }
        let W = CVPixelBufferGetWidth(buf), H = CVPixelBufferGetHeight(buf)
        let rb = CVPixelBufferGetBytesPerRow(buf)
        guard let base = CVPixelBufferGetBaseAddress(buf)?.assumingMemoryBound(to: UInt8.self) else { return (nil, nil) }
        let s = Float(input) / Float(max(W, H))                    // letterbox scale (match detector_integrate)
        let nw = Int((Float(W) * s).rounded()), nh = Int((Float(H) * s).rounded())
        guard let arr = try? MLMultiArray(shape: [1, 3, NSNumber(value: input), NSNumber(value: input)], dataType: .float32) else { return (nil, nil) }
        let ptr = arr.dataPointer.assumingMemoryBound(to: Float.self)
        let plane = input * input
        // Letterbox border = the server's ZERO-padded canvas AFTER normalisation, i.e. (0-mean)/std — NOT raw 0.
        // (Raw-0 padding is out-of-distribution and makes the detector fire a constant peak on the border.)
        for c in 0..<3 { let v = -mean[c] / std[c]; let b = c * plane; for i in 0..<plane { ptr[b + i] = v } }
        // High-quality (anti-aliased) BGRA downsample via vImage — matches the server's cv2.resize; nearest-neighbour
        // drops the small, fast ball below the detector threshold, and a hand-rolled box filter is too slow.
        var src = vImage_Buffer(data: UnsafeMutableRawPointer(mutating: base), height: vImagePixelCount(H),
                                width: vImagePixelCount(W), rowBytes: rb)
        let dstRB = nw * 4
        let dst = UnsafeMutablePointer<UInt8>.allocate(capacity: dstRB * nh); defer { dst.deallocate() }
        var dstBuf = vImage_Buffer(data: dst, height: vImagePixelCount(nh), width: vImagePixelCount(nw), rowBytes: dstRB)
        guard vImageScale_ARGB8888(&src, &dstBuf, nil, vImage_Flags(kvImageHighQualityResampling)) == kvImageNoError else { return (nil, nil) }
        for yy in 0..<nh {
            let row = yy * dstRB
            for xx in 0..<nw {
                let p = row + xx * 4                               // BGRA
                let o = yy * input + xx
                ptr[o] = (Float(dst[p + 2]) / 255 - mean[0]) / std[0]        // channel 0 = R
                ptr[plane + o] = (Float(dst[p + 1]) / 255 - mean[1]) / std[1]
                ptr[2 * plane + o] = (Float(dst[p]) / 255 - mean[2]) / std[2]
            }
        }
        guard let out = try? model.prediction(from: MLDictionaryFeatureProvider(dictionary: ["image": arr])) else { return (nil, nil) }
        guard let hm = out.featureValue(for: "heatmap")?.multiArrayValue,
              let lane = out.featureValue(for: "lane")?.multiArrayValue else { return (nil, nil) }
        // heatmap shape [1, C, O, O] (C>=1, ball = channel 0), stride-4 output. The model is exported FLOAT16, so
        // read the outputs at their actual precision (reading fp16 bits as fp32 yields garbage ~1e34 constants).
        let O = hm.shape[hm.shape.count - 1].intValue
        let st = input / O
        let readHM = Self.reader(hm), readLane = Self.reader(lane)
        var best: Float = thr; var bi = -1
        for i in 0..<(O * O) { let v = readHM(i); if v > best { best = v; bi = i } }   // ball channel = first O*O block
        var ball: ODBallDet? = nil
        if bi >= 0 {
            let hy = bi / O, hx = bi % O
            // SUB-CELL offset refinement (matches the server: cx=(px+ox)*st/s). Without it the bare stride-4 cell
            // quantises the position to ~15 px at full res → a noisy trajectory. offset shape [1,2,O,O] (ox,oy).
            var ox: Float = 0, oy: Float = 0
            if let off = out.featureValue(for: "offset")?.multiArrayValue {
                let r = Self.reader(off); ox = r(hy * O + hx); oy = r(O * O + hy * O + hx)
            }
            ball = ODBallDet(cx: (Float(hx) + ox) * Float(st) / s, cy: (Float(hy) + oy) * Float(st) / s, score: best)
        }
        // lane head: 6 params normalized by max(W,H) (match lane_from_params)
        let m = Float(max(W, H))
        let lane6 = ODLaneParams(foulL: (readLane(0) * m, readLane(1) * m), foulR: (readLane(2) * m, readLane(3) * m),
                                 vp: (readLane(4) * m, readLane(5) * m))
        return (ball, lane6)
    }

    /// Run the detector on a NATIVE-RESOLUTION crop centred at (cx,cy) — the far/small ball (~8 px) vanishes when the
    /// whole frame is downsized to the 512 input, but at native res inside a 512 crop it is full-size and precisely
    /// located. Returns the ball in FULL-FRAME coords, or nil. Port of ops/detector_integrate.detect_in_crop (#3).
    func detectInCrop(_ px: CVPixelBuffer, cx: Float, cy: Float, rot: ODRotation, thr: Float = 0.2) -> ODBallDet? {
        guard let buf = OnDeviceDecode.rotated(px, rot) else { return nil }
        CVPixelBufferLockBaseAddress(buf, .readOnly); defer { CVPixelBufferUnlockBaseAddress(buf, .readOnly) }
        let W = CVPixelBufferGetWidth(buf), H = CVPixelBufferGetHeight(buf), rb = CVPixelBufferGetBytesPerRow(buf)
        guard W >= input, H >= input, let base = CVPixelBufferGetBaseAddress(buf)?.assumingMemoryBound(to: UInt8.self) else { return nil }
        let x0 = max(0, min(Int(cx) - input/2, W - input)), y0 = max(0, min(Int(cy) - input/2, H - input))  // 512 window, clamped
        guard let arr = try? MLMultiArray(shape: [1, 3, NSNumber(value: input), NSNumber(value: input)], dataType: .float32) else { return nil }
        let ptr = arr.dataPointer.assumingMemoryBound(to: Float.self); let plane = input * input
        for yy in 0..<input {
            let row = (y0 + yy) * rb
            for xx in 0..<input {
                let p = row + (x0 + xx) * 4; let o = yy * input + xx       // BGRA, native res (no scale)
                ptr[o] = (Float(base[p + 2]) / 255 - mean[0]) / std[0]
                ptr[plane + o] = (Float(base[p + 1]) / 255 - mean[1]) / std[1]
                ptr[2 * plane + o] = (Float(base[p]) / 255 - mean[2]) / std[2]
            }
        }
        guard let out = try? model.prediction(from: MLDictionaryFeatureProvider(dictionary: ["image": arr])),
              let hm = out.featureValue(for: "heatmap")?.multiArrayValue else { return nil }
        let O = hm.shape[hm.shape.count - 1].intValue, st = input / O, read = Self.reader(hm)
        var best: Float = thr; var bi = -1
        for i in 0..<(O * O) { let v = read(i); if v > best { best = v; bi = i } }
        guard bi >= 0 else { return nil }
        let hy = bi / O, hx = bi % O
        var ox: Float = 0, oy: Float = 0
        if let off = out.featureValue(for: "offset")?.multiArrayValue {
            let r = Self.reader(off); ox = r(hy * O + hx); oy = r(O * O + hy * O + hx)   // sub-cell offset (no scale in crop)
        }
        return ODBallDet(cx: Float(x0) + (Float(hx) + ox) * Float(st), cy: Float(y0) + (Float(hy) + oy) * Float(st), score: best)
    }

    // --- lane helpers (match OnDeviceTracker) ---
    private static let BALL_IN: Float = 8.5, LANE_IN: Float = 41.5
    private func laneX(_ l: ODDetectedLane, _ y: Float) -> (Float, Float) { (l.left.a*y + l.left.b, l.right.a*y + l.right.b) }
    private func expDiam(_ l: ODDetectedLane, _ y: Float) -> Float { let (a,b) = laneX(l,y); return Self.BALL_IN/Self.LANE_IN*(b-a) }
    private func contactRow(_ l: ODDetectedLane, top: Float) -> Float {
        let k = Self.BALL_IN/Self.LANE_IN
        return (top + k*(l.right.b - l.left.b)) / (1 - k*(l.right.a - l.left.a))
    }

    /// Build a lane from the learned foul-corners + VP (left = foulL→vp, right = foulR→vp; x = a·y + b).
    private func laneFrom(_ p: ODLaneParams) -> ODDetectedLane? {
        func edge(_ p0: (Float, Float), _ p1: (Float, Float)) -> LaneEdge? {
            guard abs(p1.1 - p0.1) > 1 else { return nil }
            let a = (p1.0 - p0.0) / (p1.1 - p0.1); return LaneEdge(a: a, b: p0.0 - a*p0.1, resid: 0)
        }
        guard let le = edge(p.foulL, p.vp), let re = edge(p.foulR, p.vp) else { return nil }
        let yNear = Int(max(p.foulL.1, p.foulR.1)), yFar = Int(p.vp.1)
        // Sanity: the VP must be a plausible up-screen point (the lane head sometimes regresses garbage, e.g.
        // vpY -141764). A bogus VP makes every contactRow/u wrong → a plausible-but-wrong speed; reject instead.
        guard yNear > yFar + 60, yFar > -4000, p.vp.1 > -4000 else { return nil }
        let w = (re.a*Float(yNear)+re.b) - (le.a*Float(yNear)+le.b)
        guard abs(w) > 20, abs(w) < 4000 else { return nil }
        return ODDetectedLane(left: le, right: re, yNear: yNear, yFar: yFar, widthNearPx: abs(w))
    }

    /// LEARNED track fallback: run the detector on every frame, build a ball track + lane geometry, so the engine
    /// recovers the hard camera positions the classical tracker drops. Reuses `baseGeo`'s lane/VP when the classical
    /// lane solve succeeded (more accurate); else builds the lane from the detector's lane head. Returns nil if too
    /// few ball detections link into a monotonic down-lane track.
    func buildTrack(url: URL, rot: ODRotation, baseGeo: ODLaneGeometry) -> (BallTrack, ODLaneGeometry)? {
        let asset = AVURLAsset(url: url)
        guard let tr = asset.tracks(withMediaType: .video).first, let reader = try? AVAssetReader(asset: asset) else { return nil }
        let out = AVAssetReaderTrackOutput(track: tr, outputSettings: [kCVPixelBufferPixelFormatTypeKey as String: Int(kCVPixelFormatType_32BGRA)])
        out.alwaysCopiesSampleData = false; reader.add(out); reader.startReading()
        var raw: [(t: Double, cx: Float, cy: Float)] = []; var laneAcc: [ODLaneParams] = []; var idx = 0; var scanned = 0
        let STRIDE = 3           // run the detector on every 3rd frame — enough points for the fit, and bounds the
                                 // per-frame 3 MB MLMultiArray allocation (memory + latency) on long/120fps clips.
        while reader.status == .reading, let sb = out.copyNextSampleBuffer() {
            if Task.isCancelled { reader.cancelReading(); return nil }
            defer { idx += 1 }
            if idx % STRIDE != 0 { continue }
            autoreleasepool {
                guard let raw0 = CMSampleBufferGetImageBuffer(sb) else { return }
                let t = CMTimeGetSeconds(CMSampleBufferGetPresentationTimeStamp(sb)); scanned += 1
                let (ball, lane) = detect(raw0, rot: rot)
                if let l = lane { laneAcc.append(l) }
                if let b = ball { raw.append((t, b.cx, b.cy)) }   // (crop-refine needs a 2-pass over a validated track)
            }
        }
        Self.lastRaw = raw.map { [$0.t, Double($0.cx), Double($0.cy)] }   // parity harness
        guard raw.count >= 6 else { return nil }
        // lane: prefer the classical solve; else the median learned lane
        var lane = baseGeo.lanes.first ?? baseGeo.rawLanes.first
        var vpY: Float
        if let l = lane, let vp = baseGeo.vanishingPoint { vpY = vp.y; _ = l }
        else if !laneAcc.isEmpty {
            func med(_ f: (ODLaneParams) -> Float) -> Float { laneAcc.map(f).sorted()[laneAcc.count/2] }
            let p = ODLaneParams(foulL: (med{$0.foulL.0}, med{$0.foulL.1}), foulR: (med{$0.foulR.0}, med{$0.foulR.1}),
                                 vp: (med{$0.vp.0}, med{$0.vp.1}))
            guard let ll = laneFrom(p) else { return nil }
            lane = ll; vpY = p.vp.1
        } else { return nil }
        guard let L = lane else { return nil }
        // points → contactRow/frac; robust monotonic-u fit (drop outliers once)
        func u(_ ct: Float) -> Float { 1 / max(ct - vpY, 1) }
        var pts: [TrackPoint] = []
        for (i, r) in raw.enumerated() {
            let D = expDiam(L, r.cy); let ct = contactRow(L, top: r.cy - D/2)
            let (xa, xb) = laneX(L, ct); guard xb - xa > 1 else { continue }
            pts.append(TrackPoint(i: i, t: r.t, cx: r.cx, contactRow: ct, frac: (r.cx - xa)/(xb - xa)))
        }
        pts.sort { $0.t < $1.t }
        guard pts.count >= 6 else { return nil }
        // The detector fires on EVERY frame (pins, neighbour balls, non-shot frames too), so a plain fit over all
        // points is garbage. RANSAC the ball's u(t)=1/(ct−vpY) line: the shot is the largest set of detections on a
        // single straight, increasing-u (down-lane), positive-slope track. tol scales with the u range.
        let U = pts.map { Double(u($0.contactRow)) }
        let uSpan = max((U.max() ?? 0) - (U.min() ?? 0), 1e-4)
        let tol = max(0.06 * uSpan, 0.0015)
        var bestInl: [TrackPoint] = []
        let N = pts.count
        // cap the RANSAC SEED pairs to a uniform subsample (≤160) so it stays O(seeds²·N) on long clips; inliers are
        // still counted over ALL points.
        let cap = 160
        let stride = max(1, N / cap)
        var seeds: [Int] = []; var si = 0; while si < N { seeds.append(si); si += stride }
        for a in 0..<seeds.count {
            for b in (a+1)..<seeds.count {
                let i = seeds[a], j = seeds[b]
                let dt = pts[j].t - pts[i].t
                guard dt > 0.1 else { continue }
                let sl = (U[j] - U[i]) / dt; guard sl > 0 else { continue }
                let ic = U[i] - sl * pts[i].t
                var inl: [TrackPoint] = []
                for k in 0..<N where abs(U[k] - (sl*pts[k].t + ic)) <= tol { inl.append(pts[k]) }
                if inl.count > bestInl.count { bestInl = inl }
            }
        }
        var inl = bestInl
        guard inl.count >= 6 else { return nil }
        // one least-squares refit + re-select on the inliers (polish the RANSAC seed)
        var n=0.0,st=0.0,su=0.0,stt=0.0,stu=0.0
        for p in inl { let t=p.t, uu=Double(u(p.contactRow)); n+=1; st+=t; su+=uu; stt+=t*t; stu+=t*uu }
        let den=n*stt-st*st
        if abs(den) > 1e-9 {
            let sl=(n*stu-st*su)/den, ic=(su-sl*st)/n
            if sl > 0 { inl = pts.filter { abs(Double(u($0.contactRow)) - (sl*$0.t+ic)) <= tol } }
        }
        guard inl.count >= 6 else { return nil }
        // Constant-acceleration (quadratic) outlier rejection on ct(t): the ball decelerates smoothly, so a spurious
        // far-down-lane detection (pin/reflection false positive) that the linear-u RANSAC admits stands off the
        // quadratic. Removing it fixes the max-u "far point" that otherwise anchors the changepoint on a false event.
        if inl.count >= 8, let (qa, qb, qc) = Self.quadFit(inl.map { $0.t }, inl.map { Double($0.contactRow) }) {
            let res = inl.map { abs(Double($0.contactRow) - (qa*$0.t*$0.t + qb*$0.t + qc)) }
            let sorted = res.sorted(); let med = sorted[sorted.count/2]
            let mad = res.map { abs($0 - med) }.sorted()[res.count/2]
            let cut = max(med + 4 * (1.4826 * mad), 10.0)
            let kept = zip(inl, res).filter { $1 <= cut }.map { $0.0 }
            if kept.count >= 6 { inl = kept }
        }
        guard inl.count >= 6 else { return nil }
        // robust foul-cross: interpolate t where u(t) crosses u(foulRow) between the two bracketing track points
        // (the global linear fit is skewed by noisy down-lane small-ball positions; the near-foul ball is big and
        // well-located, so the bracket is accurate). u increases foul→pins, so find u0 < uf <= u1.
        let uf = u(Float(L.yNear))
        var foulOv: Double? = nil
        for k in 1..<inl.count {
            let u0 = u(inl[k - 1].contactRow), u1 = u(inl[k].contactRow)
            if u0 < uf, u1 >= uf, u1 != u0 {
                foulOv = inl[k - 1].t + Double((uf - u0) / (u1 - u0)) * (inl[k].t - inl[k - 1].t); break
            }
        }
        var bt = BallTrack(points: inl, framesScanned: scanned, candidateFrames: raw.count, seconds: 0)
        bt.foulCrossOverride = foulOv
        let geo = ODLaneGeometry(lanes: [L], vanishingPoint: SIMD2<Float>(0, vpY), foulLineY: L.yNear,
                                 satFloorUsed: 0, imageSize: baseGeo.imageSize)
        return (bt, geo)
    }
}
